function pm(){setTimeout(()=>{const lm=document.querySelector('.js-preload-media');let cl=false;if(lm){if(!cl){const clon=lm.content.cloneNode(true);document.querySelector('body').appendChild(clon);cl=true;}}},5000);}
pm();
function preloader(){
  const preloader=document.querySelector('.js-preloader');
  const pageWrapper=document.querySelector('.js-page-wrapper');
  const html=document.documentElement;
  
  if(preloader){
    const counter=document.querySelector('.js-preloader-count');
    
    // Check if homepage and if loaded before in this session
    const isHomepage = window.location.pathname.endsWith('index.html') || window.location.pathname.endsWith('index-alt.html') || window.location.pathname.endsWith('/hk/') || window.location.pathname.endsWith('/') || window.location.pathname === '';
    const hasLoadedBefore = sessionStorage.getItem('hnh_loaded');
    
    if (hasLoadedBefore || !isHomepage) {
      // Instant load: hide preloader, show content wrapper, trigger text stagger transitions immediately
      preloader.style.display = 'none';
      preloader.remove();
      if(pageWrapper){
        pageWrapper.style.visibility = 'visible';
      }
      html.style.overflow = 'auto';
      html.style.pointerEvents = 'auto';
      document.body.scrollTop = document.documentElement.scrollTop = 0;
      bringWebsite();
      setTimeout(() => {
        textSplitAppear();
      }, 100);
      return;
    }
    
    // First time homepage visit - run the 3s loader and set session storage
    sessionStorage.setItem('hnh_loaded', 'true');
    const MIN_LOADING_TIME=3000;
    const startTime=performance.now();
    function animateProgress(){
      function step(){
        const elapsed=performance.now()-startTime;
        const timeProgress=Math.min(elapsed/MIN_LOADING_TIME,1);
        const progress=timeProgress;
        const percent=Math.floor(progress*100);
        if(counter){
          counter.textContent=`${percent < 10 ? '0' : ''}${percent}%`;
        }
        if(percent<100){
          requestAnimationFrame(step);
        }else{
          finishLoading();
        }
      }
      requestAnimationFrame(step);
    }
    function finishLoading(){
      setTimeout(()=>{
        counter.textContent=`100%`;
        preloader.style.transition='opacity 0.5s ease';
        preloader.style.opacity=0;
        if(pageWrapper){
          pageWrapper.style.visibility='visible';
        }
        document.body.scrollTop=document.documentElement.scrollTop=0;
        bringWebsite();
        setTimeout(()=>{
          preloader.remove();
          html.style.overflow='auto';
          html.style.pointerEvents='auto';
          textSplitAppear();
        },500);
      },300);
    }
    animateProgress();
  }else{
    hnhPreloader();
    bringWebsite();
    if(pageWrapper){
      pageWrapper.style.visibility='visible';
    }
    html.style.overflow='auto';
    html.style.pointerEvents='auto';
    const textAppear=document.querySelectorAll('.js-text-split-appear span');
    if(textAppear){
      textAppear.forEach(item=>{
        item.style.opacity='1';
      });
    }
    // Trigger animations immediately for inside pages
    setTimeout(() => {
      textSplitAppear();
    }, 100);
  }
}
