function initStaticContactForm(){/* Every region's enquiry goes to all three inboxes; the subject line says which site it came from. FormSubmit only accepts one address in the endpoint, so the other two ride along as _cc. */const CONTACT_TO='business.development@harbourandhills.com';const CONTACT_CC='business.development.us@harbourandhills.com,business.development.ca@harbourandhills.com';function getRegionName(){const path=window.location.pathname.toLowerCase();const namespace=(document.querySelector('main[data-barba-namespace]')?.getAttribute('data-barba-namespace')||'').toLowerCase();const title=(document.title||'').toLowerCase();if(path.includes('/us/')||path.includes('/usa/')||namespace==='us'||namespace==='usa'||title.includes('usa')||title.includes('united states'))return 'USA';if(path.includes('/ca/')||namespace==='ca'||title.includes('canada'))return 'Canada';if(path.includes('/in/')||namespace==='in'||title.includes('india'))return 'India';if(path.includes('/hk/')||namespace==='hk'||title.includes('hong kong'))return 'Hong Kong';return 'Global';}const forms=document.querySelectorAll('form.wpcf7-form');forms.forEach(form=>{if(form.dataset.staticFormInit)return;form.dataset.staticFormInit='true';form.addEventListener('submit',async function(e){e.preventDefault();e.stopImmediatePropagation();const submitBtn=form.querySelector('input[type="submit"], button[type="submit"]');let responseOutput=form.querySelector('.wpcf7-response-output');if(!responseOutput){responseOutput=document.createElement('div');responseOutput.className='wpcf7-response-output';form.appendChild(responseOutput);}const nameInput=form.querySelector('input[name="your-name"]');const phoneInput=form.querySelector('input[name="your-phone"]');const emailInput=form.querySelector('input[name="your-email"]');const countryInput=form.querySelector('select[name="country"]');const messageInput=form.querySelector('textarea[name="your-message"]');const name=nameInput?nameInput.value.trim():'';const phone=phoneInput?phoneInput.value.trim():'';const email=emailInput?emailInput.value.trim():'';/* option zero of the country select is a label with a real value, so treat it as "nothing chosen" rather than mailing the placeholder text */const countryPlaceholder=countryInput&&countryInput.options.length?countryInput.options[0].value.trim():'';let country=countryInput?countryInput.value.trim():'';if(country&&country===countryPlaceholder){country='';}const message=messageInput?messageInput.value.trim():'';if(!name||!email||!message||(countryInput&&!country)){form.classList.remove('sent','submitting');form.classList.add('invalid');form.setAttribute('data-status','invalid');responseOutput.style.display='block';responseOutput.style.color='#dc3232';responseOutput.textContent='Please fill in all required fields.';return;}const emailRegex=/^[^\s@]+@[^\s@]+\.[^\s@]+$/;if(!emailRegex.test(email)){form.classList.remove('sent','submitting');form.classList.add('invalid');form.setAttribute('data-status','invalid');responseOutput.style.display='block';responseOutput.style.color='#dc3232';responseOutput.textContent='Please enter a valid email address.';return;}form.classList.remove('invalid','sent');form.classList.add('submitting');form.setAttribute('data-status','submitting');if(submitBtn){submitBtn.disabled=true;submitBtn.setAttribute('data-original-val',submitBtn.value||'Send');submitBtn.value='Sending...';}responseOutput.style.display='none';try{const regionName=getRegionName();const pageTitle=document.title?document.title.replace(/\s+/g,' ').trim():'Contact — Harbour & Hills';const payload={Name:name,Email:email,Phone:phone||'N/A',Region:regionName,Country:country||'N/A',Message:message,_replyto:email,_subject:'New Inquiry from Harbour & Hills '+regionName+' ('+pageTitle+')',_cc:CONTACT_CC,_template:'table',_captcha:'false'};const res=await fetch('https://formsubmit.co/ajax/'+encodeURIComponent(CONTACT_TO),{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify(payload)});if(res.ok){form.reset();form.classList.remove('submitting','invalid');form.classList.add('sent');form.setAttribute('data-status','sent');responseOutput.style.display='block';responseOutput.style.color='#1dbab0';responseOutput.style.fontWeight='bold';responseOutput.style.padding='12px 0';responseOutput.textContent='Thank you for your message. It has been sent successfully.';window.dataLayer=window.dataLayer||[];window.dataLayer.push({event:'generate_lead',form_name:'Contact',region:regionName,user_country:country||'N/A'});}else{throw new Error('Server returned '+res.status);}}catch(err){console.error('Contact form submission error:',err);form.classList.remove('submitting','sent');form.classList.add('failed');form.setAttribute('data-status','failed');responseOutput.style.display='block';responseOutput.style.color='#dc3232';responseOutput.textContent='There was an error trying to send your message. Please try again later.';}finally{if(submitBtn){submitBtn.disabled=false;submitBtn.value=submitBtn.getAttribute('data-original-val')||'Send';}}});});}
